function fqRankUrl(side, page) {
  var off = Math.max(0, (Number(page) || 1) - 1) * 30;
  return 'https://api-lf.fanqiesdk.com/api/novel/channel/homepage/rank/rank_list/v2/'
    + '?aid=13&limit=30&offset=' + off + '&side_type=' + side + '&type=1';
}
function fqCateUrl(id, gender, page, limit) {
  var lim = limit || 30;
  var off = Math.max(0, (Number(page) || 1) - 1) * lim;
  return 'https://api.fanqiesdk.com/api/novel/channel/homepage/new_category/book_list/v1/'
    + '?aid=1967&offset=' + off + '&limit=' + lim + '&category_id=' + id + '&gender=' + (gender ? 1 : 0);
}
function fqSelectUrl(type, page) {
  var off = Math.max(0, (Number(page) || 1) - 1) * 10;
  return 'https://www.fanqienovel.com/api/rank/recommend/list?type=' + type + '&limit=10&offset=' + off;
}
function fqPublicationUrl(page) {
  var idx = Math.max(0, (Number(page) || 1) - 1);
  return 'https://www.fanqienovel.com/api/node/publication/list?page_index=' + idx + '&page_count=50';
}

