 *
 * 由于我们要按页码拼 URL、又要判断 has_more，统一走「@js:」规则 + 本地函数。
 * ==========================================================================*/

/* explore 分类项的定义（会被构建脚本写进书源的 exploreUrl 字段） */
function fqExploreItems() {
